184	// Streaming parser for the strict single-block PEM structure used by key-id:
185	//
186	//   [ASCII ws] -----BEGIN PUBLIC KEY----- LF/CRLF
187	//   (base64 lines; no blank or whitespace-only lines) ...
188	//   -----END PUBLIC KEY----- LF/CRLF
189	//   [ASCII ws]
190	//
191	// Bytes are fed straight from the read passes, chunk by chunk, and nothing is
192	// retained besides the fixed-size parser state and the decoded payload: the
193	// surrounding whitespace is merely classified and discarded, and each base64
194	// quantum is decoded the moment its fourth character arrives, so no base64
195	// text is ever accumulated. Memory use therefore depends on the size of the
196	// encoded public key itself, not on the amount of whitespace around the block
197	// or on the file size; no file-size limit is imposed.
198	//
199	// Anything outside the grammar above fails deterministically: non-whitespace
200	// outside the block, more than one block, any other PEM label (private keys,
201	// certificates, PKCS#1 RSA public keys, ...), malformed or truncated base64.
202	// finish() additionally verifies that the decoded payload is one complete,
203	// canonical DER SubjectPublicKeyInfo understood by the crypto library, so
204	// non-DER BER encodings and trailing bytes are rejected as well.
205	class PublicKeyPemSink {
206	public:
207	    explicit PublicKeyPemSink(const char* pathArg) : pathArg_(pathArg) {}
208	
209	    bool start() { return true; }
210	
211	    bool consume(const char* data, size_t size) {
212	        if (failed_) {
213	            return false;  // stay failed across the rest of the file
214	        }
215	        for (size_t i = 0; i < size; ++i) {
216	            if (!feed(static_cast<unsigned char>(data[i]))) {
217	                failed_ = true;
218	                reportInvalid();
219	                return false;
220	            }
221	        }
222	        return true;
223	    }
224	
225	    bool finish() {
226	        if (failed_) {
227	            return false;  // consume() already reported the reason
228	        }
229	        bool ok = false;
230	        switch (phase_) {
231	            case Phase::kEndMarker:
232	                // A fully matched END line needs no trailing line feed at
233	                // EOF; an unfinished match is a truncated marker.
234	                ok = markerMatched_ == kPemEnd.size();
235	                break;
236	            case Phase::kEndCr:
237	                // An END line ending in CR is accepted at EOF too, exactly
238	                // as the whole-file parser stripped that final CR.
239	                ok = true;
240	                break;
241	            case Phase::kPostamble:
242	                ok = true;
243	                break;
244	            case Phase::kPreamble:       // empty or whitespace-only file
245	            case Phase::kBeginMarker:    // truncated BEGIN line
246	            case Phase::kBeginCr:        // CR in the header not followed by LF
247	            case Phase::kBodyLineStart:
248	            case Phase::kBodyData:
249	            case Phase::kBodyCr:         // truncated: no END line
250	                break;
251	        }
252	        if (ok) {
253	            ok = flushQuantumAtEnd() && validateSpkiDer();
254	        }
255	        if (!ok) {
256	            failed_ = true;
257	            reportInvalid();
258	        }
259	        return ok;
260	    }
261	
262	    // Valid only after finish() succeeded: the canonical SPKI DER.
263	    const std::vector<unsigned char>& spkiDer() const { return der_; }
264	
265	private:
266	    enum class Phase {
267	        kPreamble,
268	        kBeginMarker,
269	        kBeginCr,
270	        kBodyLineStart,
271	        kBodyData,
272	        kBodyCr,
273	        kEndMarker,
274	        kEndCr,
275	        kPostamble,
276	    };
277	
278	    bool feed(unsigned char c) {
279	        switch (phase_) {
280	            case Phase::kPreamble:
281	                if (isAsciiSpace(c)) {
282	                    return true;
283	                }
284	                if (c == static_cast<unsigned char>(kPemBegin[0])) {
285	                    markerMatched_ = 1;
286	                    phase_ = Phase::kBeginMarker;
287	                    return true;
288	                }
289	                return false;
290	
291	            case Phase::kBeginMarker:
292	                if (c == '\n') {
293	                    return markerMatched_ == kPemBegin.size() &&
294	                           beginComplete();
295	                }
296	                if (c == '\r') {
297	                    if (markerMatched_ != kPemBegin.size()) {
298	                        return false;
299	                    }
300	                    phase_ = Phase::kBeginCr;
301	                    return true;
302	                }
303	                if (markerMatched_ < kPemBegin.size() &&
304	                    c == static_cast<unsigned char>(kPemBegin[markerMatched_])) {
305	                    ++markerMatched_;
306	                    return true;
307	                }
308	                return false;
309	
310	            case Phase::kBeginCr:
311	                // A CR in the header is only legal as the CR of CRLF.
312	                return c == '\n' && beginComplete();
313	
314	            case Phase::kBodyLineStart:
315	                if (c == '-') {
316	                    markerMatched_ = 1;
317	                    phase_ = Phase::kEndMarker;
318	                    return true;
319	                }
320	                if (c == '\n') {
321	                    return false;  // no blank lines inside the block
322	                }
323	                if (isAsciiSpace(c)) {
324	                    return false;  // whitespace is allowed only around it
325	                }
326	                return feedBase64Data(c);
327	
328	            case Phase::kBodyData:
329	                if (c == '\n') {
330	                    if (lineEmpty_) {
331	                        return false;  // blank or whitespace-only line
332	                    }
333	                    lineEmpty_ = true;
334	                    phase_ = Phase::kBodyLineStart;
335	                    return true;
336	                }
337	                if (c == '\r') {
338	                    if (lineEmpty_) {
339	                        return false;
340	                    }
341	                    phase_ = Phase::kBodyCr;
342	                    return true;
343	                }
344	                if (isAsciiSpace(c)) {
345	                    return false;
346	                }
347	                return feedBase64Data(c);
348	
349	            case Phase::kBodyCr:
350	                // Bare CRs are not line separators: a CR must end with LF.
351	                if (c != '\n') {
352	                    return false;
353	                }
354	                lineEmpty_ = true;
355	                phase_ = Phase::kBodyLineStart;
356	                return true;
357	
358	            case Phase::kEndMarker:
359	                if (c == '\n') {
360	                    return markerMatched_ == kPemEnd.size() && endComplete();
361	                }
362	                if (c == '\r') {
363	                    if (markerMatched_ != kPemEnd.size()) {
364	                        return false;
365	                    }
366	                    phase_ = Phase::kEndCr;
367	                    return true;
368	                }
369	                if (markerMatched_ < kPemEnd.size() &&
370	                    c == static_cast<unsigned char>(kPemEnd[markerMatched_])) {
371	                    ++markerMatched_;
372	                    return true;
373	                }
374	                return false;
375	
376	            case Phase::kEndCr:
377	                return c == '\n' && endComplete();
378	
379	            case Phase::kPostamble:
380	                // Everything still in the file must be ASCII whitespace; a
381	                // second block or any appended text is rejected, not ignored.
382	                return isAsciiSpace(c);
383	        }
384	        return false;
385	    }
386	
387	    bool beginComplete() {
388	        phase_ = Phase::kBodyLineStart;
389	        lineEmpty_ = true;
390	        return true;
391	    }
392	
393	    bool endComplete() {
394	        phase_ = Phase::kPostamble;
395	        return true;
396	    }
