398	    static int base64Value(unsigned char c) {
399	        if (c >= 'A' && c <= 'Z') return c - 'A';
400	        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
401	        if (c >= '0' && c <= '9') return c - '0' + 52;
402	        if (c == '+') return 62;
403	        if (c == '/') return 63;
404	        return -1;
405	    }
406	
407	    // Feeds one character of a payload line. '-' is deliberately outside the
408	    // alphabet (it starts the END marker, handled by the caller), so any other
409	    // PEM boundary fails here rather than being consumed. Decoding is strict
410	    // and canonical, quantum by quantum; padding is legal only as the
411	    // conventional "x=" / "xx==" tail of the stream, and its unused bits must
412	    // be zero. This mirrors the former whole-file decoder exactly.
413	    bool feedBase64Data(unsigned char c) {
414	        phase_ = Phase::kBodyData;
415	        lineEmpty_ = false;
416	
417	        quantum_[quantumLen_++] = c;
418	        if (quantumLen_ < 4) {
419	            return true;  // wait for the rest of the quantum
420	        }
421	        quantumLen_ = 0;
422	
423	        const int a = base64Value(quantum_[0]);
424	        const int b = base64Value(quantum_[1]);
425	        if (a < 0 || b < 0) {
426	            return false;
427	        }
428	
429	        const bool pad2 = quantum_[2] == '=';
430	        const bool pad3 = quantum_[3] == '=';
431	        if (sawPadding_) {
432	            return false;  // no complete quantum may follow a padded one
433	        }
434	
435	        if (pad2) {
436	            if (!pad3) {
437	                return false;  // '=' at position 2 requires one at position 3
438	            }
439	            if ((b & 0x0f) != 0) {
440	                return false;  // non-canonical: unused padding bits must be 0
441	            }
442	            der_.push_back(static_cast<unsigned char>((a << 2) | (b >> 4)));
443	            sawPadding_ = true;
444	        } else {
445	            const int cv = base64Value(quantum_[2]);
446	            if (cv < 0) {
447	                return false;
448	            }
449	            if (pad3) {
450	                if ((cv & 0x03) != 0) {
451	                    return false;  // non-canonical: unused padding bits must be 0
452	                }
453	                der_.push_back(
454	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
455	                der_.push_back(static_cast<unsigned char>(
456	                    ((b & 0x0f) << 4) | (cv >> 2)));
457	                sawPadding_ = true;
458	            } else {
459	                const int d = base64Value(quantum_[3]);
460	                if (d < 0) {
461	                    return false;
462	                }
463	                der_.push_back(
464	                    static_cast<unsigned char>((a << 2) | (b >> 4)));
465	                der_.push_back(static_cast<unsigned char>(
466	                    ((b & 0x0f) << 4) | (cv >> 2)));
467	                der_.push_back(static_cast<unsigned char>(
468	                    ((cv & 0x03) << 6) | d));
469	            }
470	        }
471	        return true;
472	    }
473	
474	    // At EOF the payload must have ended on a quantum boundary and must
475	    // decode to at least one byte.
476	    bool flushQuantumAtEnd() {
477	        if (quantumLen_ != 0 || der_.empty()) {
478	            return false;
479	        }
480	        return true;
481	    }
482	
483	    // Validates that the decoded payload is one complete SubjectPublicKeyInfo
484	    // DER structure covering every byte, understood by the crypto library, and
485	    // in canonical encoding. Re-encoding the parsed structure must reproduce
486	    // the payload byte for byte; that round trip rules out non-DER BER
487	    // encodings and other representations OpenSSL might otherwise accept. The
488	    // bytes hashed for the fingerprint are therefore the canonical SPKI DER,
489	    // so PEM line wrapping and line endings never influence the result.
490	    bool validateSpkiDer() {
491	        const unsigned char* p = der_.data();
492	        const std::unique_ptr<EVP_PKEY, decltype(&EVP_PKEY_free)> pkey(
493	            d2i_PUBKEY_ex(nullptr, &p, static_cast<long>(der_.size()), nullptr,
494	                          nullptr),
495	            &EVP_PKEY_free);
496	        if (!pkey) {
497	            return false;
498	        }
499	        if (p - der_.data() != static_cast<ptrdiff_t>(der_.size())) {
500	            return false;  // trailing bytes after the SPKI structure
501	        }
502	
503	        const int encLen = i2d_PUBKEY(pkey.get(), nullptr);
504	        if (encLen <= 0 || static_cast<size_t>(encLen) != der_.size()) {
505	            return false;
506	        }
507	        std::vector<unsigned char> reencoded(static_cast<size_t>(encLen));
508	        unsigned char* q = reencoded.data();
509	        if (i2d_PUBKEY(pkey.get(), &q) != encLen || reencoded != der_) {
510	            return false;  // non-canonical DER
511	        }
512	        return true;
513	    }
514	
515	    void reportInvalid() const {
516	        std::cerr << "sealmark: '" << pathArg_
517	                  << "' does not contain a single valid PEM-encoded "
518	                     "SubjectPublicKeyInfo public key (PUBLIC KEY)\n";
519	    }
520	
521	    Phase phase_ = Phase::kPreamble;
522	    size_t markerMatched_ = 0;  // prefix length of the marker being matched
523	    bool lineEmpty_ = true;     // current body line has seen no data yet
524	    unsigned char quantum_[4] = {};
525	    size_t quantumLen_ = 0;
526	    bool sawPadding_ = false;  // a padded (final) quantum already occurred
527	    bool failed_ = false;
528	    const char* pathArg_ = nullptr;
529	    std::vector<unsigned char> der_;
530	};
