532	// Renders bytes as lowercase hexadecimal with no separators or prefix.
533	std::string toHexLower(const unsigned char* data, size_t size) {
534	    static constexpr char kHex[] = "0123456789abcdef";
535	    std::string out;
536	    out.reserve(2 * size);
537	    for (size_t i = 0; i < size; ++i) {
538	        out.push_back(kHex[data[i] >> 4]);
539	        out.push_back(kHex[data[i] & 0x0f]);
540	    }
541	    return out;
542	}
