544	int digestFile(const char* pathArg) {
545	    Sha256StreamSink sink(pathArg);
546	    if (!processFileChunks(pathArg, sink)) {
547	        return 1;
548	    }
549	
550	    std::cout << kDigestPrefix
551	              << toHexLower(sink.hash(), kSha256Size) << '\n';
552	    return 0;
553	}
