555	// Accepts only "sha256:" followed by exactly 64 lowercase hexadecimal
556	// characters: no missing prefix, no uppercase, no other algorithm names,
557	// no surrounding whitespace or trailing content.
558	bool isValidExpectedDigest(std::string_view digest) {
559	    if (digest.size() != kDigestPrefix.size() + kDigestHexLen) {
560	        return false;
561	    }
562	    if (digest.substr(0, kDigestPrefix.size()) != kDigestPrefix) {
563	        return false;
564	    }
565	    for (size_t i = kDigestPrefix.size(); i < digest.size(); ++i) {
566	        const char c = digest[i];
567	        const bool isHex =
568	            (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
569	        if (!isHex) {
570	            return false;
571	        }
572	    }
573	    return true;
574	}
