576	int verifyDigestFile(const char* pathArg, std::string_view expected) {
577	    Sha256StreamSink sink(pathArg);
578	    if (!processFileChunks(pathArg, sink)) {
579	        return 1;
580	    }
581	
582	    std::string actual;
583	    actual.reserve(kDigestPrefix.size() + kDigestHexLen);
584	    actual.append(kDigestPrefix);
585	    actual.append(toHexLower(sink.hash(), kSha256Size));
586	
587	    if (actual == expected) {
588	        std::cout << "match\n";
589	        return 0;
590	    }
591	    std::cout << "mismatch\n";
592	    return 3;
593	}
