595	int keyIdFile(const char* pathArg) {
596	    PublicKeyPemSink sink(pathArg);
597	    if (!processFileChunks(pathArg, sink)) {
598	        return 1;
599	    }
600	
601	    const std::vector<unsigned char>& spkiDer = sink.spkiDer();
602	    unsigned char hash[kSha256Size];
603	    unsigned int hashLen = 0;
604	    if (EVP_Digest(spkiDer.data(), spkiDer.size(), hash, &hashLen,
605	                   EVP_sha256(), nullptr) != 1 ||
606	        hashLen != kSha256Size) {
607	        std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg
608	                  << "'\n";
609	        return 1;
610	    }
611	
612	    std::cout << kSpkiFingerprintPrefix
613	              << toHexLower(hash, kSha256Size) << '\n';
614	    return 0;
615	}
